function btn(label,action,args=[],variant='primary',extra=''){return `<button ${/\btype=/.test(extra)?'':'type="button"'} class="button ${variant}" data-action="${action}" ${args.map((v,i)=>`data-arg${i}="${esc(v)}"`).join(' ')} ${extra}>${label}</button>`;}
function icon(name){return `<span class="icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">${HCA_PATHS[name]||CC_ART_ICONS[name]||HCA_PATHS.spark}</svg></span>`;}
