function chip(label,kind=''){return `<span class="chip ${kind}">${esc(label)}</span>`;}
function disclosure(text='Illustrative · fictional learning'){return `<span class="disclosure">${icon('shield')}${esc(text)}</span>`;}
function empty(title,text,action='library',label='Explore learning'){return `<div class="empty"><span class="empty-symbol">${icon('book')}</span><h3>${title}</h3><p>${text}</p>${btn(label,'navigate',[action],'secondary')}</div>`;}
function header(title,subtitle,eyebrow='YOUR LEARNING SPACE'){return `<header class="page-heading"><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${subtitle}</p></header>`;}
function progress(value,label){return `<div class="progress" role="progressbar" aria-label="${esc(label)}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(value)}"><span style="width:${Math.max(0,Math.min(100,value))}%"></span></div>`;}
function ring(value){return `<span class="ring" style="--progress:${Math.round(value)}" aria-label="${Math.round(value)} percent complete"><b>${Math.round(value)}%</b></span>`;}
function ccIsDark(){return state.theme==='dark'||(state.theme==='system'&&matchMedia('(prefers-color-scheme: dark)').matches);}
function studioReducedMotion(){return state.reduceMotion||matchMedia('(prefers-reduced-motion: reduce)').matches;}
function applyPreferences(){const root=document.documentElement;root.dataset.theme=ccIsDark()?'dark':'light';root.dataset.motion=studioReducedMotion()?'reduce':'full';root.dataset.dyslexia=String(state.dyslexia===true);root.style.setProperty('--text-scale',state.textSize===21?'1.25':state.textSize===19?'1.125':'1');document.body.classList.toggle('theme-dark',ccIsDark());document.body.classList.toggle('hca-reduce',studioReducedMotion());}
function persist(){store.save();}function persistQuiet(){store.save();}function hcaSave(){store.save();}
function localDay(date=new Date()){return date.getFullYear()+'-'+String(date.getMonth()+1).padStart(2,'0')+'-'+String(date.getDate()).padStart(2,'0');}
function laterDay(days=1){const d=new Date();d.setDate(d.getDate()+days);return localDay(d);}
function due(id){return !!state.reviewQueue[id]&&state.reviewQueue[id].due<=localDay();}
function hcaDue(){return lessons.filter(l=>due(l.id)).map(lesson=>({lesson,...state.reviewQueue[lesson.id]}));}
function status(l){return due(l.id)?'Review due':state.completed.includes(l.id)?'Reviewed':state.checkRecords.some(r=>r.lesson===l.id)||state.lastSession?.lesson===l.id?'In progress':'Not started';}
function footer(){return `<footer class="app-footer"><span>© ${new Date().getFullYear()} Healthcare Crown Academy</span><nav aria-label="Legal information">${btn('About','info',['about'],'ghost')}${btn('Privacy','info',['privacy'],'ghost')}${btn('Sources','info',['sources'],'ghost')}</nav></footer>`;}
