function guideVisual(index){return `<div class="guide-preview" aria-hidden="true"><div class="guide-preview-brand"><img src="${HCA_CREST}" alt=""><span>Carecraft <small>YOUR LEARNING SPACE</small></span><i></i><i></i><i></i></div><div class="guide-preview-content"><span class="guide-preview-tag">${APP_GUIDE[index].label.toUpperCase()}</span><div class="guide-preview-icon">${icon(APP_GUIDE[index].icon)}</div><div class="guide-preview-lines"><i></i><i></i></div><div class="guide-preview-cards">${(index===0?['Learn','Try','Reflect']:index===1?['Learn','Check','Reflect']:index===2?['Choose','Decide','Review']:index===3?['Open','Edit','Keep']:['Notice','Return','Grow']).map((s,i)=>`<span><b>0${i+1}</b>${s}</span>`).join('')}</div><div class="guide-preview-bottom"><span></span><i>✓</i></div></div></div>`;}
function openAppGuide(index=0){ui.guideStep=Math.max(0,Math.min(4,Number(index)||0));showModal('Make yourself at home.','A quick guide to Carecraft',`<div class="app-guide-shell"><nav class="app-guide-tabs" aria-label="Choose a guide chapter">${APP_GUIDE.map((g,i)=>btn(icon(g.icon)+'<span>'+g.label+'</span>','app-guide-step',[i],'ghost',`aria-pressed="${i===ui.guideStep}"`)).join('')}</nav><div id="appGuidePanel"></div><div class="app-guide-pagination"><button type="button" class="button secondary" data-action="app-guide-step" id="guidePrev">← Back</button><span id="guideStatus" role="status" aria-live="polite"></span><button type="button" class="button secondary" data-action="app-guide-step" id="guideNext">Next →</button></div></div>`);$('#modal').classList.add('app-guide-modal');changeAppGuide(ui.guideStep);}
function changeAppGuide(index){if(!$('#modal').classList.contains('app-guide-modal'))return;index=Math.max(0,Math.min(4,Number(index)||0));ui.guideStep=index;const g=APP_GUIDE[index];$('#appGuidePanel').innerHTML=`<div class="app-guide-chapter">${guideVisual(index)}<div class="app-guide-copy"><span class="eyebrow">CHAPTER 0${index+1} OF 05 · ${g.label.toUpperCase()}</span><h3>${g.title}</h3><p class="guide-lead">${g.lead}</p><ol class="guide-instructions">${g.steps.map(([title,text],i)=>`<li><span>${i+1}</span><div><h4>${title}</h4><p>${text}</p></div></li>`).join('')}</ol><p class="guide-tip">${icon('spark')}<span>${g.tip}</span></p>${btn(g.cta,'guide-go',[g.route])}</div></div>`;$('#guideStatus').textContent=(index+1)+' of 5 · '+g.label;for(const [id,n]of [['guidePrev',index-1],['guideNext',index+1]]){const b=$('#'+id);b.dataset.arg0=n;b.disabled=n<0||n>4;}document.querySelectorAll('.app-guide-tabs button').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===index)));}
function appGuideKey(event){if(!$('#modal')?.open||!$('#modal').classList.contains('app-guide-modal')||!event.target.closest('.app-guide-tabs')||!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return false;event.preventDefault();changeAppGuide(event.key==='Home'?0:event.key==='End'?4:ui.guideStep+(event.key==='ArrowRight'?1:-1));document.querySelectorAll('.app-guide-tabs button')[ui.guideStep].focus();return true;}

function ccGuideFor(key){const sim=CC_SIMS.find(s=>s.id===key),s=sim||CC_STUDIOS.find(s=>s.id===key),l=lessons.find(l=>l.id===key);if(s)return {title:s.title,what:s.description,why:s.why,when:s.when,how:s.how,who:'Individual learners, peer pairs and facilitators. Fictional learning practice.',evidence:s.evidence};if(l)return {title:l.title,what:l.description,why:l.takeaway,when:CC_USE[l.id]?.[1]||'Before practice or when reflecting on this topic.',how:l.steps.map((s,i)=>(i+1)+'. '+s[0]).join('. '),who:CC_USE[l.id]?.[0]||'Healthcare learners and practitioners.',evidence:l.evidence};const map={hygiene:'infection','sbar-studio':'sbar',movement:'wellbeing',room:'infection',cus:'speakup',huddle:'accountability',flow:'human-factors',teach:'teachback-skill',reflect:'debrief',evidence:'risk-evidence',qi:'improvement',desc:'conflict',fishbone:'human-factors',handover:'sbar',teachback:'teachback-skill','ai-case':'ai','med-case':'med-transitions',pause:'wellbeing'};if(map[key])return ccGuideFor(map[key]);const a=CC_SECTIONS[key]||CC_SECTIONS.practice;return Object.fromEntries(['title','what','why','when','how','who','evidence'].map((k,i)=>[k,a[i]]));}
function openGuide(id,trigger){const g=ccGuideFor(id),p=$('#quickGuide');p.innerHTML=`<div class="section-title"><h3>${esc(g.title)}</h3>${btn('×','close-guide',[],'icon-button','aria-label="Close guide"')}</div><dl>${['what','why','when','how','who'].map(k=>`<dt>${k[0].toUpperCase()+k.slice(1)}</dt><dd>${esc(g[k])}</dd>`).join('')}</dl>${btn('Explore supporting evidence →','guide-evidence',[g.evidence],'secondary')}`;p.classList.add('is-open');if(p.showPopover)try{p.showPopover();}catch{}const r=trigger?.getBoundingClientRect();if(r){p.style.left=Math.max(12,Math.min(innerWidth-430,r.left))+'px';p.style.top=Math.max(12,Math.min(innerHeight-420,r.bottom+8))+'px';}p.querySelector('button')?.focus();ui.guideTrigger=trigger;}
function closeGuide(){const p=$('#quickGuide');try{p.hidePopover?.();}catch{}p.classList.remove('is-open');ui.guideTrigger?.focus();}
function previewLesson(id){const l=lessons.find(l=>l.id===id);showModal('A little context. A useful next step.',l.title,`<img class="preview-art" src="${ccTopicArtwork(id,l.cat)}" alt="Topic artwork for ${esc(l.tag)}"><p class="lead">${esc(l.description)}</p>${ccLearningBrief(l)}<h3>Inside this lesson</h3><ol>${l.steps.map(([t])=>`<li>${esc(t)}</li>`).join('')}</ol><p>${esc(l.takeaway)}</p>${btn('Begin this lesson →','lesson',[id])}`);}
function lessonEvidence(id){const l=lessons.find(l=>l.id===id);showModal('Evidence & sources',l.title,`${ccEvidenceHTML(l.evidence)}<details open><summary>Supporting resources & editorial context</summary><p>Original educational synthesis and fictional practice. Independent clinical peer review remains pending. No accreditation or endorsement is implied.</p>${refsHtml(l)}<p>Three practice prompts include an explanation for every option. Suggested review intervals are a learning aid, not a validated assessment.</p></details>`);}
function ccShowEvidence(id,target){if(!CC_EVIDENCE[id])return;if($('#modal').open&&(ui.activity||ui.tool)){let p=$('#contextPanel');if(p)p.remove();$('#modalBody').insertAdjacentHTML('beforeend',`<section class="context-panel" id="contextPanel" tabindex="-1">${btn('Close evidence','close-evidence',[],'ghost')}${ccEvidenceHTML(id)}</section>`);$('#contextPanel').focus();ui.evidenceTrigger=target;}else showModal('The finding and its context.',CC_EVIDENCE[id].source,ccEvidenceHTML(id));}
function ccOpenEvidence(filter='all'){showModal('Evidence & sources','13 topic-matched references · Published findings, with their limits.',`<p>These are external research results, not Carecraft outcomes. Read the study design, population, context and limitations together.</p><div class="segmented">${[['all','All 13'],['reviews','Reviews'],['studies','Studies & surveillance']].map(([v,t])=>btn(t,'evidence',[v],v===filter?'selected':'ghost')).join('')}</div><div class="evidence-grid">${Object.entries(CC_EVIDENCE).filter(([,e])=>filter==='all'||(filter==='reviews'?/review|meta-analysis/i.test(e.type):!/review|meta-analysis/i.test(e.type))).map(([id])=>ccEvidenceHTML(id)).join('')}</div>`);}
function showInfo(kind){const legal=`<section class="company-details"><h3>Healthcare Crown Academy</h3><p>HEALTHCARE CROWN ACADEMY LTD · Registered in England and Wales · Company no. 17501904<br>71–75 Shelton Street, Covent Garden, London WC2H 9JQ · ICO registration ZC273259</p><p>Educational activity, not clinical certification or accredited CPD/CME.</p></section>`;showModal(kind==='about'?'The practice of better care.':kind==='privacy'?'Your learning stays with you.':'Sources & editorial notes','Healthcare Crown Academy',CC_STATIC_CONTENT[kind]+(kind==='about'?legal:kind==='privacy'?'<h3>Carecraft v4.0.1 on this device</h3><p>Notes, highlights, recent searches and activity checkpoints are saved locally. Backups and text exports include your notes. Read aloud uses an on-device English voice when available; no text is sent to a speech service.</p>':''));}
function openAbout(){showInfo('about');}function hcaOpenAbout(){showInfo('about');}function openPrivacy(){showInfo('privacy');}function openSources(){showInfo('sources');}function hcaOpenProfile(){showSettings();}function openProfile(){showSettings();}
function showSettings(){showModal('Make this space yours.','A useful starting point, with room to change.',renderSettings());}
function saveSettings(){captureDraft();state.name=$('#prefName').value.trim();state.role=$('#prefRole').value;state.learningFocus=$('#prefFocus').value;state.setting=$('#prefSetting').value;state.textSize=+$('#prefText').value;state.goal=+$('#prefMinutes').value;ui.minutes=[2,5,10].includes(state.goal)?state.goal:5;state.reduceMotion=$('#prefMotion').checked;state.dyslexia=$('#prefDyslexia').checked;state.onboarded=true;store.save(true);closeModal(true);render();toast('Preferences saved for this device.');}
