function setTheme(mode){state.theme=mode;persist();refreshAppearance();appearance();}
function showData(){showModal('Your data. Your choice.','Private notes stay on this device.',`<p id="storageStatus">${store.ok?'Your learning data is saved in this browser.':'Storage is unavailable. Export a backup before leaving.'}</p><div class="data-options">${btn('Export learning record ↓','export')}${btn('Download backup ↓','backup',[],'secondary')}${btn('Restore a backup','restore',[],'secondary')}${btn('Download this app ↓','download-app',[],'secondary')}${btn('Print learning record','print',[],'secondary')}${btn('Reset this workspace','reset-confirm',[],'ghost')}</div><p>Backups include private reflections and notes. Keep them in a place you trust.</p>`);}
function hcaBackup(){downloadFile(store.export(),'carecraft-backup-'+localDay()+'.json','application/json');toast('Backup downloaded. Keep it private.');}
function hcaCheckBackup(b){return store.validate(b);}
function hcaChooseBackup(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.addEventListener('change',async()=>{const file=input.files[0];if(!file)return;try{if(file.size>8*1024*1024)throw Error('Choose a backup smaller than 8 MB.');const backup=JSON.parse(await file.text());store.validate(backup);ui.pendingBackup=backup;showModal('Restore this learning workspace?','Current data will be replaced. You can undo immediately after restoring.',`<p>Backup from ${esc(new Date(backup.exportedAt).toLocaleString())}. Download a backup of your current workspace if you want to keep both.</p><div class="row">${btn('Back up current data','backup',[],'secondary')}${btn('Restore this backup','restore-confirm')}</div>`);}catch(e){toast(e.message||'That backup could not be read. Current data is unchanged.');}});input.click();}
function hcaRestoreBackup(){if(!ui.pendingBackup)return;captureDraft();const before=store.import(ui.pendingBackup);ui.pendingBackup=null;ui.suspendCapture=true;closeModal(true);navigate('progress');ui.suspendCapture=false;toast('Learning workspace restored.',()=>{state=store.migrate(before);store.save(true);render();});}
function confirmReset(){showModal('Reset this learning workspace?','Download a backup first if you want to keep your records.',`<p>This clears this browser’s Carecraft profile, notes, bookmarks and learning records. Downloaded files stay on your device.</p><div class="row">${btn('Download a backup','backup',[],'secondary')}${btn('Reset this workspace','reset')}</div>`);}
function resetData(){ui.suspendCapture=true;closeModal(true);state=store.migrate({});store.save(true);ui.review=null;lessonAnswers={};navigate('dashboard');ui.suspendCapture=false;toast('This workspace has been reset.');}
function exportProgress(print=false){captureDraft();const lines=['CARECRAFT / HEALTHCARE CROWN ACADEMY','RECORD OF LEARNING ACTIVITY, NOT A CREDENTIAL','Educational activity, not clinical certification or accredited CPD/CME.','Exported: '+new Date().toLocaleString(),'Name: '+(state.name||'Not provided'),'Role: '+state.role,'','REVIEWED LESSONS',...state.completed.map(id=>lessons.find(l=>l.id===id)?.title||id),'','REFLECTIONS',...Object.entries(state.reflections).map(([id,v])=>(lessons.find(l=>l.id===id)?.title||id)+'\n'+v),'','NOTES & HIGHLIGHTS',...state.notes.map(n=>(lessons.find(l=>l.id===n.lesson)?.title||n.lesson)+'\n'+(n.quote||'')+'\n'+(n.text||'')),'','ACTION PLANS',...state.actions.map(a=>a.text+'\nStatus: '+a.status+' | Review: '+a.due+'\n'+(a.review||'')),'','LESSON CHECKS',...state.checkRecords.map(r=>(lessons.find(l=>l.id===r.lesson)?.title||r.lesson)+' | '+r.date+' | '+(r.correct?'More helpful response':'Alternative explored')),'','PRACTICE TRAIL',...state.studioAttempts.map(a=>a.label+'\n'+a.detail),'','SCENARIOS',...state.branchRecords.map(r=>(cases.find(c=>c.id===r.case)?.title||r.case)+'\n'+r.path.map(p=>p.label+' — '+p.feedback).join('\n'))];if(print){$('#learningRecord').innerHTML=`<h1>Carecraft learning record</h1><p>Record of learning activity, not a credential.</p><pre>${esc(lines.join('\n'))}</pre>`;window.print();}else downloadFile(lines.join('\n'),'carecraft-learning-record.txt');}
function ccPortableHTML(){const code=$('#carecraft-app-code')?.textContent,styles=$('#carecraft-app-styles')?.textContent;if(!code?.includes('function renderHome')||!styles?.includes('--surface'))throw Error('Complete app source unavailable.');return '<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="carecraft-version" content="4.0.1"><title>Carecraft v4.0.1 — Healthcare Crown Academy</title><style id="carecraft-app-styles">'+styles+'</style></head><body><div id="app"></div><script id="carecraft-app-code">'+code.replace(/<\/script/gi,'<\\/script')+'</scr'+'ipt></body></html>';}
function hcaDownloadApp(){downloadFile(ccPortableHTML(),CC_RELEASE.filename,'text/html');}
function openTool(id){captureDraft();captureActivity();exitPresent();clearSelection();studioPause();advStop();if($('#modal').open)closeModal(true);ui.activity=null;ui.tool=id;ui.dirty=false;if(id.startsWith('adv-')){launchActivity(id.slice(4));return;}if(id==='movement'){launchActivity('movement');return;}if(workspaceSpecs[id]){openWorkspace(id);return;}if(id==='evidence'){openEvidenceWorkspace();return;}legacyOpenTool(id);if(id==='reflect'&&$('#reflection')){$('#reflection').dataset.draft='general';}}
function openWorkspace(id){const s=workspaceSpecs[id],values=toolValues(id);showModal(s.title,s.sub,`${disclosure('Fictional practice draft · not a clinical record')}<p class="footnote">${esc(s.note)} Private drafts stay on this device.</p><div class="row">${btn('Load poor example','workspace-example',[id,'poor'],'secondary')}${btn('Load stronger example','workspace-example',[id,'good'],'secondary')}${btn('Clear draft','workspace-clear',[id],'ghost')}</div><label>Other examples<select data-field="workspace-alt" data-key="${id}"><option value="">Choose a fictional example…</option><option value="good2">Stronger example B</option><option value="poor2">Poor example B</option></select></label>${id==='fishbone'?'<figure><canvas id="causeCanvas" role="img" aria-label="Cause-and-effect diagram. Editable categories and values follow." style="width:100%;aspect-ratio:1000/480"></canvas><figcaption class="footnote">Possible contributors are hypotheses. Investigate before drawing conclusions.</figcaption></figure>':''}<div class="workspace-grid"><div>${s.fields.map((f,i)=>`<label>${esc(f)}<textarea id="toolField${i}" maxlength="1500" data-field="workspace" data-key="${id}">${esc(values[i]||'')}</textarea></label>`).join('')}</div><aside class="tool-preview"><h3>Your practice draft</h3><div id="toolPreview">${workspacePreview(id,values)}</div></aside></div><div class="row">${btn('Download my draft ↓','workspace-download',[id],'secondary')}${btn('Plan one action →','tool-reflect',[id])}</div>${ccActivityBrief(id)}`);if(id==='fishbone')drawCauseCanvas();}
function loadWorkspaceExample(id,kind){const before=toolValues(id).slice(),spec=workspaceSpecs[id],values=(kind==='good'||kind==='poor')?spec[kind]:alternateSamples[id]?.[kind==='good2'?'good':'poor'];if(!values)return;state.toolDrafts[id]=values.slice();persist();openWorkspace(id);toast('Fictional example loaded.',()=>{state.toolDrafts[id]=before;persist();openWorkspace(id);});}
function loadExpandedExample(id,kind){if(kind)loadWorkspaceExample(id,kind);}
function clearWorkspace(id){const before=toolValues(id).slice();state.toolDrafts[id]=workspaceSpecs[id].fields.map(()=>'');persist();openWorkspace(id);toast('Draft cleared.',()=>{state.toolDrafts[id]=before;persist();openWorkspace(id);});}
function updateWorkspace(id){const values=workspaceSpecs[id].fields.map((_,i)=>$('#toolField'+i)?.value||'');state.toolDrafts[id]=values;persist();$('#toolPreview').innerHTML=workspacePreview(id,values);if(id==='fishbone')drawCauseCanvas();}
function startCase(id){ui.activity=id;ccCurrentGuide=id;branchSession={case:id,stage:0,path:[],firstHelpful:false,selected:null};renderCase();}
function branchQuestion(){const b=branchData[branchSession.case],c=cases.find(c=>c.id===branchSession.case),stage=branchSession.stage;let raw=stage===2?HCA_FINALES[branchSession.case]:stage===0?{event:c.body,question:c.question,answers:b.choices,correct:b.correct,rationales:b.rationales}:{event:branchSession.firstHelpful?b.success:b.recovery,question:branchSession.firstHelpful?b.successQ:b.recoveryQ,answers:[b.alternatives[0],b.good,b.alternatives[1]],correct:1,rationales:['This leaves an important uncertainty or responsibility unresolved.',b.debrief,'This postpones or transfers the unresolved issue rather than establishing a clear plan.']};branchSession.orders=branchSession.orders||{};const order=branchSession.orders[stage]||(branchSession.orders[stage]=hcaShuffle(raw.answers.length));return {...raw,answers:order.map(i=>raw.answers[i]),rationales:order.map(i=>raw.rationales[i]),correct:order.indexOf(raw.correct)};}
function finishBranch(){let record=state.branchRecords.find(r=>r.id===branchSession.savedId);if(!record){record={id:'branch-'+Date.now(),case:branchSession.case,path:branchSession.path,date:new Date().toISOString()};state.branchRecords.push(record);branchSession.savedId=record.id;if(!state.cases.includes(record.case))state.cases.push(record.case);persist();}showBranchDebrief(record,branchData[branchSession.case]);}
function selectStudio(tab){studioDispose();studioTab=tab;currentPage='studio';ui.activity=tab==='sbar'?'sbar-studio':tab;render();recordRoute();}
function hcaLaunchStudio(tab){selectStudio(tab);}
function launchActivity(id){if(!HCA_ACTIVITIES.some(a=>a.id===id)){toast('Choose an available activity from Practice.');return;}captureDraft();captureActivity();exitPresent();studioDispose();advStop();clearSelection();ui.review=null;if($('#modal').open)closeModal(true);ui.tool=null;ui.activity=id;ui.activitySaved=false;ui.history=[];ui.dirty=false;ccCurrentGuide=id;const a=HCA_ACTIVITIES.find(a=>a.id===id);if(!a)return;if(id==='room')hcaOpenRoom();else if(['hygiene','sbar-studio','movement'].includes(id)){selectStudio(id==='sbar-studio'?'sbar':id);}else if(cases.some(c=>c.id===id))startCase(id);else if(CC_STUDIOS.some(s=>s.id===id))ccOpenStudio(id);else if(CC_SIMS.some(s=>s.id===id))ccOpenSimulation(id);else openAdv(id);captureActivity();}
function activityFinished(){if(!ui.activity)return false;if(ui.activitySaved)return true;if(ccStudio?.id===ui.activity)return ccStudio.saved||ccStudio.checked||ccStudio.history?.length===3;if(ccSim?.id===ui.activity)return ccSim.finished;if(branchSession?.case===ui.activity)return branchSession.stage>=3;if(ui.activity==='room')return hcaRoom.index>=6;if(ui.activity==='hygiene')return hygieneIndex>=6;if(ui.activity==='sbar-studio')return sbarChecked&&sbarAcknowledged;return false;}
function finishExtras(){if(!ui.activity||!activityFinished())return '';const a=HCA_ACTIVITIES.find(a=>a.id===ui.activity),next=HCA_ACTIVITIES[(HCA_ACTIVITIES.indexOf(a)+1)%HCA_ACTIVITIES.length];return `<section class="finish-screen"><span class="eyebrow">WHAT YOU PRACTISED</span><h3>${esc(a?.title||'A useful decision')}</h3><p>${esc(a?.desc||'Review your reasoning and choose a next action.')}</p><h4>One thing to try</h4><p>${esc(ccGuideFor(ui.activity).why)}</p><p class="footnote">Use the activity’s Save control to keep its full trail in My Growth. Records describe learning activity, not clinical competence.</p>${btn('Next activity →','activity',[next.id],'secondary')}${btn('View My Growth','navigate',['progress'],'ghost')}</section>`;}
function captureActivity(){if(!ui.activity)return;let snapshot;if(CC_STUDIOS.some(s=>s.id===ui.activity))snapshot={ccStudio};else if(CC_SIMS.some(s=>s.id===ui.activity))snapshot={ccSim};else if(cases.some(c=>c.id===ui.activity))snapshot={branchSession};else if(ui.activity==='room')snapshot={hcaRoom};else snapshot={studioTab,hygieneIndex,hygieneAnswers,hygieneSelected,hotspotSelected,sbarSlots,sbarSelected,sbarChecked,sbarGuided,sbarAcknowledged,movementId,movementSafety,movementCycles,advMode,cusStep,cusSelected,cusHistory,huddleStep,huddleHistory,simStep,simServed,simQueue,simRework,simHistory,simCapacity};state.lastSession={kind:'activity',id:ui.activity,snapshot:JSON.parse(JSON.stringify({...snapshot,activitySaved:!!ui.activitySaved})),date:new Date().toISOString()};store.save();}
function resumeTitle(){const s=state.lastSession;return s?.kind==='activity'?HCA_ACTIVITIES.find(a=>a.id===s.id)?.title||'Your practice':lessons.find(l=>l.id===s?.lesson)?.title||'Your next lesson';}
function restoreCheckpoint(saved){const x=saved.snapshot||{};ui.activity=saved.id;ui.activitySaved=!!x.activitySaved;if(x.ccStudio){ccStudio=x.ccStudio;ccRenderStudio();}else if(x.ccSim){ccSim=x.ccSim;ccSim.playing=false;ccRenderSimulation();}else if(x.branchSession){branchSession=x.branchSession;renderCase();}else if(x.hcaRoom){hcaRoom=x.hcaRoom;hcaRenderRoom();}else{({studioTab,hygieneIndex,hygieneAnswers,hygieneSelected,hotspotSelected,sbarSlots,sbarSelected,sbarChecked,sbarGuided,sbarAcknowledged,movementId,movementSafety,movementCycles,advMode,cusStep,cusSelected,cusHistory,huddleStep,huddleHistory,simStep,simServed,simQueue,simRework,simHistory,simCapacity}=x);if(['cus','huddle','flow'].includes(saved.id))({cus:renderCus,huddle:renderHuddle,flow:renderFlow})[saved.id]();else{currentPage='studio';render();recordRoute();}}captureActivity();}
function resume(){const saved=structuredClone(state.lastSession);if(!saved)return;if(saved.kind!=='activity'){openLesson(saved.lesson,saved.tab||'learn');hcaConfigureQuestion(saved.lesson,saved.question||0);render();return;}launchActivity(saved.id);ui.dirty=true;restoreCheckpoint(saved);}
