function actionValue(v){if(v==='true')return true;if(v==='false')return false;if(v==='null')return null;if(v!==''&&Number.isFinite(Number(v)))return Number(v);return v;}
function dispatchAction(element,event,type='click'){const key=type==='click'?'action':'on'+type,name=element.dataset[key];if(!name)return;const args=[];for(let i=0;element.hasAttribute('data-arg'+i);i++)args.push(element.getAttribute('data-arg'+i));if(name.startsWith('engine-')){if(['dragover','dragleave'].includes(type)){ENGINE_ACTIONS[name]?.(event,element,args);return;}if(/(?:resetHygiene|resetSbar|hcaOpenRoom|ccOpenStudio|ccOpenSimulation|openAdv|setFlowCapacity|ccRiskChange)\s*\(/.test(ENGINE_ACTIONS[name]?.toString()||'')){ui.activitySaved=false;ui.lastSavedAttempt=null;ui.history=[];}if(['click','change','drop'].includes(type)&&ui.activity&&!activityFinished()&&!/ccShowEvidence|closeModal|logStudio|ccSave|saveFlowLearning/.test(ENGINE_ACTIONS[name]?.toString()||'')){captureActivity();(ui.history||(ui.history=[])).push(structuredClone(state.lastSession));ui.history=ui.history.slice(-50);}const encoded=element.getAttribute('data-'+name);if(encoded){try{args.splice(0,args.length,...JSON.parse(encoded));}catch{return;}}if(!['closeModal','ccShowEvidence'].some(s=>ENGINE_ACTIONS[name]?.toString().includes(s)))ui.dirty=!!ui.activity;ENGINE_ACTIONS[name]?.(event,element,args);}else actions[name]?.(args,event,element);captureActivity();syncActivityUI();}
function handleClick(event){if(!event.target.closest('.profile-menu'))document.querySelectorAll('.profile-menu[open]').forEach(d=>d.open=false);const element=event.target.closest('[data-action]');if(!element||element.disabled)return;event.stopPropagation();dispatchAction(element,event);document.querySelectorAll('.profile-menu[open]').forEach(d=>{if(!event.target.closest('summary'))d.open=false;});}
function handleInput(event){const el=event.target,field=el.dataset.field;if(el.dataset.oninput)dispatchAction(el,event,'input');if(!field)return;if(field==='reflection'){state.reflections[el.dataset.draft||activeLesson.id]=el.value;persist();}else if(field==='action-draft')saveActionDraft();else if(field==='action-review'){const a=state.actions.find(a=>a.id===el.dataset.key);if(a){a.review=el.value;persist();}}else if(field==='workspace'){ui.dirty=true;updateWorkspace(el.dataset.key);}else if(['palette-search','page-search'].includes(field)){ui.query=el.value;ui.searchIndex=0;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{const out=field==='palette-search'?$('#paletteResults'):$('#pageResults');if(out)out.innerHTML=searchResults(ui.query);if(field==='page-search')recordRoute(true);},120);}}
function handleChange(event){const el=event.target,field=el.dataset.field;if(el.dataset.onchange)dispatchAction(el,event,'change');if(field==='learn-filter'){ui.filters[el.dataset.key]=el.value;render();}else if(field==='practice-filter'){ui.practice[el.dataset.key]=el.value;render();}else if(field==='workspace-alt')loadExpandedExample(el.dataset.key,el.value);else if(field==='action-status'){const a=state.actions.find(a=>a.id===el.dataset.key);if(a){a.status=el.value;persist();}}else if(field==='speech-speed')ui.readSpeed=+el.value;}
function activityNextTarget(host){return Array.from(host.querySelectorAll('button:not(:disabled)')).find(b=>/^(Next|Follow the next|See (?:my )?debrief|Continue|Review decision|Show the next|Reveal the next|Check my sequence|Step)/i.test(b.textContent.trim())&&!b.closest('#presentControls,.activity-stepbar'));}
function presentStep(direction){const host=$('#modal').open?$('#modal'):$('#main');if(direction<0){activityBack();return;}activityNextTarget(host)?.click();}
function syncActivityUI(){if(!ui.activity)return;const host=$('#modal').open?$('#modal'):$('#main'),next=host.querySelector('[data-action="activity-next"]'),back=host.querySelector('[data-action="activity-back"]');if(next){next.disabled=!activityNextTarget(host);next.setAttribute('aria-label',next.disabled?'Choose a response or use the activity controls first':'Continue to the next activity step');}if(back)back.disabled=!ui.history?.length||activityFinished();if(currentPage==='studio'&&!$('#modal').open){const finish=$('#main .finish-screen');if(activityFinished()&&!finish)$('#studioWorkbench')?.insertAdjacentHTML('afterend',finishExtras());else if(!activityFinished())finish?.remove();}}

function handleKey(event){if(event.defaultPrevented)return;if(infographicKey(event)||appGuideKey(event))return;const typing=event.target.matches('input,textarea,select,[contenteditable="true"]');if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();openPalette();return;}if(event.target.dataset.onkeydown)dispatchAction(event.target,event,'keydown');if(event.key==='Escape'){if($('#quickGuide').classList.contains('is-open')){closeGuide();event.preventDefault();return;}if($('#modal').open){event.preventDefault();closeModal();return;}const profile=$('.profile-menu[open]');if(profile){profile.open=false;profile.querySelector('summary').focus();}else toggleMenu(false);return;}if((($('#modal').open&&$('#modal').classList.contains('command-palette'))||event.target.id==='pageSearch')&&['ArrowUp','ArrowDown','Enter'].includes(event.key)){event.preventDefault();const items=ui.searchResults||[];if(event.key==='Enter'){chooseSearch(ui.searchIndex);return;}ui.searchIndex=(ui.searchIndex+(event.key==='ArrowDown'?1:-1)+items.length)%Math.max(1,items.length);document.querySelectorAll('.search-result').forEach(e=>{const on=+e.dataset.arg0===ui.searchIndex;e.classList.toggle('active',on);e.setAttribute('aria-selected',String(on));});($('#paletteSearch')||$('#pageSearch'))?.setAttribute('aria-activedescendant','result-'+ui.searchIndex);$('#result-'+ui.searchIndex)?.scrollIntoView({block:'nearest'});return;}if(event.key==='Tab'&&$('#sidebar').classList.contains('open')&&matchMedia('(max-width:760px)').matches){const f=Array.from($('#sidebar').querySelectorAll('button,a'));if(event.shiftKey&&document.activeElement===f[0]){event.preventDefault();f.at(-1).focus();}else if(!event.shiftKey&&document.activeElement===f.at(-1)){event.preventDefault();f[0].focus();}return;}if(!typing&&['Enter',' '].includes(event.key)&&event.target.matches('[role="link"][data-action]')){event.preventDefault();dispatchAction(event.target,event);return;}if(typing||$('#modal').open&&!ui.present)return;if(event.key==='/'){event.preventDefault();openPalette();return;}if(event.key==='?'){event.preventDefault();openShortcuts();return;}if(event.key==='g'&&shortcutPrefix!=='g'){shortcutPrefix='g';clearTimeout(shortcutTimer);shortcutTimer=setTimeout(()=>shortcutPrefix='',1200);return;}if(shortcutPrefix==='g'){shortcutPrefix='';const page=({h:'dashboard',l:'library',p:'practice',t:'tools',g:'progress'})[event.key];if(page){event.preventDefault();navigate(page);}return;}if(['ArrowLeft','ArrowRight'].includes(event.key)){if(ui.present){event.preventDefault();presentStep(event.key==='ArrowRight'?1:-1);}else if(currentPage==='lesson'){event.preventDefault();const tabs=['learn','practice','reflect'],i=tabs.indexOf(lessonTab);changeLessonTab(tabs[Math.max(0,Math.min(2,i+(event.key==='ArrowRight'?1:-1)))]);}return;}if(['j','k'].includes(event.key)){const cards=Array.from(document.querySelectorAll('#main [role="link"]')),i=cards.indexOf(document.activeElement);cards[(i+(event.key==='j'?1:-1)+cards.length)%cards.length]?.focus();event.preventDefault();}else if(event.key==='s'){const id=document.activeElement.closest('[data-card-id]')?.dataset.cardId||(currentPage==='lesson'?activeLesson?.id:null);if(id){event.preventDefault();toggleSave(id);}}}
function bootstrap(){shell();applyPreferences();restoreRoute();recordRoute(true);toggleMenu(false);document.addEventListener('click',handleClick);document.addEventListener('input',handleInput);document.addEventListener('change',handleChange);document.addEventListener('keydown',handleKey);document.addEventListener('mouseup',selectionChanged);document.addEventListener('keyup',e=>{if(e.key==='Shift')selectionChanged();});for(const type of ['dragstart','dragover','dragleave','drop'])document.addEventListener(type,e=>{const el=e.target.closest('[data-on'+type+']');if(el)dispatchAction(el,e,type);});$('#modal').addEventListener('cancel',e=>{e.preventDefault();closeModal();});window.addEventListener('popstate',()=>{captureActivity();if($('#modal').open)closeModal(true);restoreRoute();});window.addEventListener('hashchange',()=>{if(location.hash!=='#/'+routeString())restoreRoute();});window.addEventListener('pagehide',()=>{captureDraft();captureActivity();store.flush();});window.addEventListener('resize',()=>{if(!matchMedia('(max-width:760px)').matches){$('#sidebar').inert=false;$('.workspace').inert=false;$('.bottom-nav').inert=false;document.body.classList.remove('menu-open');}else{const open=$('#sidebar').classList.contains('open');$('#sidebar').inert=!open;$('.workspace').inert=open;$('.bottom-nav').inert=open;document.body.classList.toggle('menu-open',open);}});const color=matchMedia('(prefers-color-scheme: dark)');color.addEventListener?.('change',()=>{if(state.theme==='system')refreshAppearance();});const motion=matchMedia('(prefers-reduced-motion: reduce)');motion.addEventListener?.('change',()=>{applyPreferences();if(studioReducedMotion()){studioPause();advStop();if(ccSim){ccSim.playing=false;ccSimMotion();}clearInterval(ui.quoteTimer);ui.quoteTimer=null;}});store.save();}

/* The 60-second scenario: a first-visit hook and a daily Today card built only from each lesson's authored check, answers and rationales. */
const HOOK_FIRST=['communication','sbar','speakup','deterioration','teachback-skill','safety'];
function scenarioState(){if(!state.scenarios||typeof state.scenarios!=='object'||Array.isArray(state.scenarios))state.scenarios={seen:false,days:{}};if(!state.scenarios.days||typeof state.scenarios.days!=='object')state.scenarios.days={};return state.scenarios;}
function scenarioPool(){return lessons.filter(l=>l.question&&Array.isArray(l.answers)&&l.answers.length>1&&Array.isArray(l.rationales));}
function scenarioOfDay(day=localDay()){const pool=scenarioPool(),n=Math.floor(Date.parse(day+'T12:00:00Z')/864e5);return pool[((n%pool.length)+pool.length)%pool.length];}
function scenarioStreak(){const days=scenarioState().days;let d=new Date(),count=0;if(!days[localDay(d)])d.setDate(d.getDate()-1);while(days[localDay(d)]){count++;d.setDate(d.getDate()-1);}return count;}
function scenarioStats(){const all=Object.values(scenarioState().days);return {answered:all.length,strongest:all.filter(x=>x.correct).length,streak:scenarioStreak()};}
function scenarioBody(l,where,chosen=null){const done=chosen!==null,letters=['A','B','C','D'];
 return `<p class="scenario-question" id="${where}-question">${esc(l.question)}</p>
 <div class="scenario-options" role="group" aria-labelledby="${where}-question">${l.answers.map((a,i)=>{const cls=!done?'':i===l.correct?'is-strongest':i===chosen?'is-chosen':'is-other';return `<button type="button" class="scenario-option ${cls}" data-action="scenario-answer" data-arg0="${where}" data-arg1="${esc(l.id)}" data-arg2="${i}" ${done?'disabled':''} ${done&&i===chosen?'aria-current="true"':''}><span class="scenario-letter" aria-hidden="true">${i===l.correct&&done?'✓':letters[i]}</span><span class="scenario-text"><span>${esc(a)}</span>${done?`<small>${i===l.correct?'<b>Strongest choice.</b> ':''}${esc(l.rationales[i]||'')}</small>`:''}</span></button>`;}).join('')}</div>
 ${done?`<div class="scenario-reveal" role="status"><span class="eyebrow">${chosen===l.correct?'YOU CHOSE THE STRONGEST RESPONSE':'A USEFUL COMPARISON'}</span><p>${esc(l.feedback)}</p><p class="scenario-takeaway">${icon('spark')}<span>${esc(l.takeaway)}</span></p></div>`:''}`;}
function scenarioFooter(l,where){return where==='hook'?`<div class="scenario-next"><p>You just practised <strong>${esc(l.title)}</strong>. The full lesson takes about ${l.time} minutes.</p><div class="row">${btn('Open the full lesson →','scenario-lesson',[l.id])}${btn('Try another scenario','scenario-another',[l.id],'secondary')}${btn('Explore Carecraft','scenario-close',[],'ghost')}</div></div>`:`<div class="row scenario-card-actions">${btn('Open the lesson →','lesson',[l.id],'secondary')}${btn('Visual guide','infographics',[l.id],'ghost')}</div>`;}
function renderDailyScenario(){const l=scenarioOfDay(),today=scenarioState().days[localDay()],chosen=today&&today.id===l.id?today.choice:null,s=scenarioStats();
 return `<section class="scenario-card" aria-labelledby="daily-question-title"><div class="scenario-card-main"><div class="scenario-card-head"><span class="eyebrow" id="daily-question-title">TODAY’S 60-SECOND SCENARIO · ${esc(l.tag.toUpperCase())}</span><span class="scenario-chip">Fictional · Practice only</span></div><div id="dailyScenario">${scenarioBody(l,'daily',chosen)}</div>${chosen!==null?scenarioFooter(l,'daily'):''}</div>
 <div class="scenario-card-side" role="group" aria-label="Your scenario rhythm"><div class="scenario-flame" aria-hidden="true">${icon('spark')}</div><strong>${s.streak}</strong><span>day${s.streak===1?'':'s'} in a row</span><dl><div><dt>Scenarios explored</dt><dd>${s.answered}</dd></div><div><dt>Strongest choices</dt><dd>${s.strongest}</dd></div></dl><p>A new scenario arrives each day. Thinking first, then comparing, helps ideas stick.</p></div></section>`;}
function answerScenario(where,id,choice){const l=lessons.find(x=>x.id===id);if(!l)return;choice=Number(choice);const s=scenarioState(),day=localDay();if(where==='daily'||!s.days[day])s.days[day]={id,choice,correct:choice===l.correct};s.seen=true;persist();
 const host=where==='hook'?$('#hookScenario'):$('#dailyScenario');if(!host)return;host.innerHTML=scenarioBody(l,where,choice);host.insertAdjacentHTML('afterend',scenarioFooter(l,where));if(where==='hook'){$('#ccHook')?.classList.add('is-answered');stopHookTimer();}
 if(where==='daily'){const side=$('.scenario-card-side');if(side){const st=scenarioStats();side.querySelector('strong').textContent=st.streak;side.querySelector('strong+span').textContent='day'+(st.streak===1?'':'s')+' in a row';const dd=side.querySelectorAll('dd');dd[0].textContent=st.answered;dd[1].textContent=st.strongest;}}
 host.querySelector('.scenario-option.is-strongest')?.focus({preventScroll:true});}
let hookTimer=null;
function stopHookTimer(){clearInterval(hookTimer);hookTimer=null;}
function openHook(id){const pool=scenarioPool(),l=pool.find(x=>x.id===id)||pool.find(x=>x.id===HOOK_FIRST[0])||pool[0];if(!l)return;let d=$('#ccHook');if(!d){d=document.createElement('dialog');d.id='ccHook';d.className='cc-hook';d.setAttribute('aria-labelledby','hookTitle');document.body.append(d);d.addEventListener('cancel',e=>{e.preventDefault();closeHook();});}
 d.classList.remove('is-answered');d.dataset.id=l.id;
 d.innerHTML=`<div class="cc-hook-inner"><header class="cc-hook-head"><div class="cc-hook-brand"><img src="${HCA_CREST}" alt="" width="40" height="40"><span>Carecraft<small>HEALTHCARE CROWN ACADEMY</small></span></div><button type="button" class="cc-hook-skip" data-action="scenario-close">Skip intro</button></header>
 <div class="cc-hook-intro"><span class="eyebrow">A 60-SECOND SCENARIO · ${esc(l.tag.toUpperCase())}</span><h2 id="hookTitle">One moment from a working day.<br><em>What would you do?</em></h2><div class="cc-hook-timer" aria-hidden="true"><svg viewBox="0 0 44 44"><circle cx="22" cy="22" r="19" class="track"/><circle cx="22" cy="22" r="19" class="fill" pathLength="100" stroke-dasharray="100" stroke-dashoffset="100" id="hookRing"/></svg><span id="hookClock">60</span></div><p class="cc-hook-note">No pressure: the ring is only a gentle pace. Choose, then compare the reasoning behind every option.</p></div>
 <div id="hookScenario">${scenarioBody(l,'hook')}</div></div>`;
 if(!d.open)d.showModal();stopHookTimer();const started=Date.now(),ring=$('#hookRing'),clock=$('#hookClock');
 if(!studioReducedMotion())hookTimer=setInterval(()=>{const t=Math.min(60,(Date.now()-started)/1000);if(ring)ring.setAttribute('stroke-dashoffset',String(100-t/60*100));if(clock)clock.textContent=String(Math.ceil(60-t));if(t>=60){stopHookTimer();if(clock)clock.textContent='✓';}},250);
 d.querySelector('.scenario-option')?.focus({preventScroll:true});}
function closeHook(){stopHookTimer();const s=scenarioState();if(!s.seen){s.seen=true;persist();}const d=$('#ccHook');if(d?.open)d.close();d?.remove();if(currentPage==='dashboard')render();}
function maybeOpenHook(){try{if(scenarioState().seen||state.onboarded||currentPage!=='dashboard'||new URLSearchParams(location.search).has('nohook'))return;openHook(HOOK_FIRST[0]);}catch{}}
Object.assign(actions,{
 'scenario-answer':([where,id,choice])=>answerScenario(where,id,choice),
 'scenario-lesson':([id])=>{closeHook();openLesson(id);},
 'scenario-another':([id])=>{const pool=scenarioPool(),order=HOOK_FIRST.filter(x=>pool.some(l=>l.id===x)),next=order[(order.indexOf(id)+1)%order.length]||pool[0].id;openHook(next);},
 'scenario-close':()=>closeHook(),
 'scenario-open':([id])=>openHook(id)
});

let studioTab='hygiene';
let hygieneIndex=0;
let hygieneAnswers=[];
