let movementSafety=false;
let movementCycles=1;
let studioRuntime=null;
let branchSession=null;
let advMode='';
let advPlaying=false;
let advTimer=null;
let cusStep=0;
let cusSelected=null;
let cusHistory=[];
let huddleStep=0;
let huddleHistory=[];
let simStep=0;
let simServed=0;
