function studioWorkbench(){if(studioTab==='hygiene')return hygieneWorkbench();if(studioTab==='sbar')return sbarWorkbench();return movementWorkbench()}
function hygieneWorkbench(){let finished=hygieneIndex>=hygieneScenes.length,s=hygieneScenes[Math.min(hygieneIndex,5)],caption=finished?'Every pause is a chance to protect the next interaction.':s.caption;return `<header class="studio-workbench-top"><div><h2>The moments that matter</h2><p>Identify the hand-hygiene indication, not the technique.</p></div><span class="pill skills">Clinical practice</span></header><div class="studio-workbench-body"><div class="studio-visual">${studioCanvas('Illustrative care room with a patient, practitioner, clean-task tray, bedside table, and hand-rub station.',caption,`<span class="studio-scene-step">${finished?'DEBRIEF':`SCENE ${hygieneIndex+1} / 6`}</span>${[[56,47,'Patient contact'],[80,34,'Clean-task area'],[79,67,'Exposure-risk task'],[71,54,'Patient surroundings'],[14,42,'Hand-hygiene station']].map(([x,y,text],i)=>`<button class="studio-hotspot" style="left:${x}%;top:${y}%" aria-label="Explore ${text}" aria-pressed="${hotspotSelected===i}" data-action="engine-0" data-engine-0="${esc(JSON.stringify([i]))}">${i+1}<span>${text}</span></button>`).join('')}`)}${studioPlayback('hygiene')}<div style="padding:0 18px 16px;font-size:var(--t-12);color:var(--muted);background:var(--surface)">Click the numbered hotspots to explore the room. No procedure is being demonstrated.</div></div><div class="studio-side" id="hygieneSide">${hygieneSide()}</div></div>${studioFoot('who','Independent fictional vignettes. A single action may meet overlapping moments. Gloves do not replace hand hygiene.')}`}
function studioFoot(source,extra){let s=STUDIO_SOURCES[source];return `<div class="studio-references"><span>${extra} Original Carecraft illustration; no source endorsement.</span><a href="${s.url}" target="_blank" rel="noopener noreferrer" title="${s.label}">[${s.n}] ${s.label} ↗</a><button class="text-link" style="font-size:var(--t-12);white-space:nowrap" data-action="engine-1" data-engine-1="[]">About the inspiration ↗</button></div>`}
function openStudioSources(){showModal('Inspired by good learning design.','Original interactions. Transparent sources.',`<p>Carecraft’s new studio uses original illustrations and code. It does not reproduce branded graphics, videos, game assets, or proprietary tools. These references informed the learning formats; this is not a popularity ranking or an affiliation.</p><h3>Interaction inspiration</h3><p>WHO’s hand-hygiene game uses scenario-based learning. Resuscitation Council UK’s Lifesaver uses interactive emergency scenarios. Oxford University Hospitals provides physiotherapy exercise demonstrations that are intended to be taught by qualified physiotherapists.</p>${['game','lifesaver','oxford'].map(k=>studioSourceLink(k)).join('')}<h3>Content references</h3><p>The hygiene vignettes use the Five Moments framework; SBAR uses AHRQ’s communication structure; seated movement cues are adapted from NHS guidance. The animation is a simplified editorial interpretation, not a validated clinical demonstration.</p>${['who','sbar','nhs'].map(k=>studioSourceLink(k)).join('')}<div class="notice" style="margin-top:18px">Sources checked 14 October 2026. No independent clinical peer review, accreditation, endorsement, real-time movement assessment, or clinical-skill validation is claimed. Obtain appropriate professional review before institutional deployment.</div>`)}
function studioSourceLink(k){let s=STUDIO_SOURCES[k];return `<p style="font-size:var(--t-12);overflow-wrap:anywhere;margin:12px 0"><b>${s.label}</b><br><a href="${s.url}" target="_blank" rel="noopener noreferrer">Open source ↗</a></p>`}
function studioCanvas(label,caption,extras=''){return `<div class="studio-canvas-wrap"><canvas id="studioCanvas" class="studio-canvas" role="img" aria-label="${label}">${label}. A complete text description and controls accompany this illustration.</canvas><span class="studio-scene-label">◉ &nbsp; ORIGINAL ANIMATED ILLUSTRATION</span>${extras}</div><div class="studio-canvas-caption" id="studioCaption">${caption}</div>`}
function studioPlayback(kind){return `<div class="studio-controls"><button class="studio-control primary" id="studioPlay" data-action="engine-2" data-engine-2="[]" aria-label="Play animation">▶ Play ${kind==='movement'?'demo':'scene'}</button><button class="studio-control" data-action="engine-3" data-engine-3="[]" aria-label="Replay animation from beginning">↺ Replay</button><button class="studio-control" data-action="engine-4" data-engine-4="[]" aria-label="Advance to next animation step">▹ Step</button><label class="push" for="studioSpeed">Speed <select id="studioSpeed" data-onchange="engine-5" data-engine-5="[]"><option value="0.5">0.5×</option><option value="1" selected>1×</option><option value="1.5">1.5×</option></select></label></div>`}
function toggleStudioPlayback(){if(!studioRuntime)return;studioRuntime.playing?studioPause():studioStart()}
function studioPause(){if(!studioRuntime)return;studioRuntime.playing=false;cancelAnimationFrame(studioRuntime.raf);studioUpdatePlayback()}
function studioUpdatePlayback(){let b=$('#studioPlay');if(b&&studioRuntime){b.textContent=studioRuntime.playing?'Ⅱ Pause':'▶ Play '+(studioTab==='movement'?'demo':'scene');b.setAttribute('aria-label',studioRuntime.playing?'Pause animation':'Play animation')}}
function studioStart(){if(!studioRuntime)return;if(studioTab==='movement'&&!movementSafety){toast('Please read and acknowledge the movement safety guidance first.');$('#movementSafety')?.focus();return}let r=studioRuntime,max=studioTab==='movement'?movements[movementId].duration*movementCycles:studioTab==='sbar'?17:Infinity;if(r.time>=max)r.time=0;r.playing=true;r.last=0;cancelAnimationFrame(r.raf);r.raf=requestAnimationFrame(studioTick);studioUpdatePlayback()}
function studioTick(now){let r=studioRuntime;if(!r||!r.playing)return;if(r.last)r.time+=Math.min((now-r.last)/1000,.06)*r.speed;r.last=now;let max=studioTab==='movement'?movements[movementId].duration*movementCycles:studioTab==='sbar'?17:Infinity;if(r.time>=max){r.time=max;studioDraw();studioPause();let e=$('#movementStatus');if(e)e.textContent='Illustration complete. The counter reflects demo loops only. You may replay, change movement, or reflect.';return}studioDraw();r.raf=requestAnimationFrame(studioTick)}
function studioDraw(){let r=studioRuntime;if(!r)return;let rect=r.canvas.getBoundingClientRect();if(!rect.width||!rect.height)return;let dpr=Math.min(window.devicePixelRatio||1,2),w=Math.round(rect.width*dpr),h=Math.round(rect.height*dpr);if(r.canvas.width!==w||r.canvas.height!==h){r.canvas.width=w;r.canvas.height=h}let ctx=r.ctx;ctx.setTransform(w/720,0,0,h/500,0,0);ctx.clearRect(0,0,720,500);if(studioTab==='hygiene')drawHygiene(ctx,r.time);else if(studioTab==='sbar')drawSbar(ctx,r.time);else drawMovement(ctx,r.time)}
