function startAssessment(){assessmentIndex=0;assessmentAnswers=[];renderAssessment()}
function renderAssessment(){if(assessmentIndex===3){let min=Math.min(...assessmentAnswers),focus=assessmentQuestions[assessmentAnswers.indexOf(min)][0];state.assessment={focus,answers:assessmentAnswers,date:new Date().toISOString().slice(0,10)};persist();showModal('A useful place to start.','Your self-reflection, not a competency assessment.',`<div class="takeaway"><div class="eyebrow">YOUR SUGGESTED FOCUS</div><h2 style="text-transform:capitalize">${focus}</h2><p style="margin-top:9px">${{knowledge:'Strengthen your foundations in safety, clinical reasoning, and digital literacy.',skills:'Build practical habits for communication, handovers, and shared decisions.',attitudes:'Make space for empathy, cultural humility, speaking up, and sustainable practice.'}[focus]}</p></div><p>This suggestion uses your lowest confidence rating. If ratings are equal, it starts with the first dimension. It is only a starting point; you know your needs and role best.</p><div class="modal-actions"><button class="btn secondary" data-action="engine-87" data-engine-87="[]">Reflect again</button><button class="btn" data-action="engine-88" data-engine-88="${esc(JSON.stringify([focus]))}">Explore my focus ↗</button></div>`);if(currentPage==='dashboard'||currentPage==='pathways')render();return}let [cat,q]=assessmentQuestions[assessmentIndex];showModal('Your practice. Your next step.',`Reflection ${assessmentIndex+1} of 3 · About 2 minutes`,`<div class="progress-track"><div style="width:${assessmentIndex/3*100}%"></div></div><span class="pill ${cat}" style="margin-top:15px">${cat}</span><p class="question" style="margin-top:18px">${q}</p><p>Think about your recent experience. There are no right or wrong answers.</p><div class="assessment-options">${[['○','Building confidence','I would value support'],['◐','Finding my rhythm','I am growing'],['●','Feeling confident','I want to refine']].map(([icon,title,sub],i)=>`<button data-action="engine-89" data-engine-89="${esc(JSON.stringify([i]))}"><span class="ico">${icon}</span><b>${title}</b><small>${sub}</small></button>`).join('')}</div><small class="muted">This self-check is not a validated clinical assessment.</small>${assessmentIndex?'<div class="modal-actions"><button class="text-link" data-action="engine-90" data-engine-90="[]">← Previous reflection</button></div>':''}`)}
function updateStudioLog(){let el=$('#studioLog');if(el)el.innerHTML=studioLogHtml();document.querySelectorAll('.studio-tab-check').forEach(el=>{let tab=el.dataset.tab;el.textContent=studioLogged(tab)||(tab==='movement'&&studioRecords().some(r=>r.id.startsWith('movement-')))?'✓':''})}
function studioLogged(id){return studioRecords().some(r=>r.id===id)}
function showBranchDebrief(r,b){showModal('A decision trail. A next useful step.','Learning choices, not a competency score.',`<div class="takeaway"><p>${b.debrief}</p></div>${r.path.map((p,i)=>`<div class="journey-card"><div class="eyebrow muted">DECISION ${i+1}</div><h4>${esc(p.label)}</h4><p>${esc(p.feedback)}</p></div>`).join('')}<div class="modal-actions"><button class="btn secondary" data-action="engine-28" data-engine-28="[]">Back to practice</button><button class="btn" data-action="engine-91" data-engine-91="${esc(JSON.stringify([b.lesson]))}">Plan one action →</button></div>`);}
